/* prog23_longest_common_prefix.c
 *
 * Re‑implementation of the original binary's behaviour.
 *
 *   - If no strings are supplied (argc < 2)          → prints "EMPTY"
 *   - If more than 64 strings are supplied (argc>65) → prints "TOO_MANY"
 *   - If any string exceeds 1024 characters          → prints "TOO_LONG"
 *   - Otherwise prints the longest common prefix of all
 *     supplied strings, followed by a newline.
 *
 * The program returns 0 in all cases.
 */

#include <stdio.h>
#include <string.h>

#define MAX_ARGS   65      /* including program name */
#define MAX_STRLEN 1024    /* maximum allowed length of each argument */

int main(int argc, char **argv)
{
    /* 1. Argument count checks */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    if (argc > MAX_ARGS) {
        puts("TOO_MANY");
        return 0;
    }

    /* 2. Length check for each argument */
    for (int i = 1; i < argc; ++i) {
        if ((size_t)strlen(argv[i]) > MAX_STRLEN) {
            puts("TOO_LONG");
            return 0;
        }
    }

    /* 3. Compute longest common prefix */
    const char *first = argv[1];
    size_t prefix_len = strlen(first);

    for (int i = 2; i < argc; ++i) {
        const char *s = argv[i];
        size_t j = 0;
        while (j < prefix_len && first[j] == s[j]) {
            ++j;
        }
        prefix_len = j;               /* shrink prefix to the common part */
        if (prefix_len == 0) {
            break;                    /* no common prefix any more */
        }
    }

    /* 4. Output the prefix character‑by‑character, then a newline */
    for (size_t i = 0; i < prefix_len; ++i) {
        putc(first[i], stdout);
    }
    putc('\n', stdout);

    return 0;
}
